package app.moviebox.mobile;

import android.Manifest;
import android.app.*;
import android.content.*;
import android.graphics.*;
import android.graphics.drawable.GradientDrawable;
import android.net.Uri;
import android.os.*;
import android.view.*;
import android.view.inputmethod.InputMethodManager;
import android.widget.*;
import androidx.media3.exoplayer.offline.*;
import org.json.*;
import java.util.*;
import java.util.concurrent.*;

@androidx.annotation.OptIn(markerClass = androidx.media3.common.util.UnstableApi.class)
public class MainActivity extends Activity {
    final int BG=Color.rgb(12,16,24),CARD=Color.rgb(23,29,40),INK=Color.rgb(240,244,247),MUTED=Color.rgb(155,166,182),ACCENT=Color.rgb(196,241,106);
    final String[] providerNames={"MovieBox","4KHDHub","Dramachi","CircleFTP · BDIX","DhakaFlix · BDIX"};
    final String[] providerIds={"moviebox","fourkhdhub","dramachi","bdix_circleftp","bdix_dhakaflix"};
    final ExecutorService io=Executors.newFixedThreadPool(4);
    final Handler main=new Handler(Looper.getMainLooper());
    LinearLayout root,body,nav; String screen="browse",provider="moviebox",query=""; int page=1,generation=0; JSONObject detail; JSONArray catalog=new JSONArray();
    EditText search; TextView status; LinearLayout results; ProgressBar progress;
    final Runnable refreshDownloads=new Runnable(){public void run(){if(screen.equals("downloads")){renderDownloads();main.postDelayed(this,1500);}}};
    @Override public void onCreate(Bundle state){super.onCreate(state);getWindow().setStatusBarColor(BG);getWindow().setNavigationBarColor(BG);
        if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=android.content.pm.PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},4);
        if(state!=null){provider=state.getString("provider","moviebox");query=state.getString("query","");}
        if(getIntent().getBooleanExtra("downloads",false))showDownloads();else showBrowse();
        checkInBackground();
    }
    @Override protected void onSaveInstanceState(Bundle out){out.putString("provider",provider);out.putString("query",query);super.onSaveInstanceState(out);}
    @Override protected void onDestroy(){generation++;main.removeCallbacks(refreshDownloads);io.shutdownNow();super.onDestroy();}
    @Override public void onBackPressed(){if(!screen.equals("browse"))showBrowse();else super.onBackPressed();}
    int dp(float n){return (int)(n*getResources().getDisplayMetrics().density+.5f);}
    GradientDrawable shape(int color,int radius){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(radius));return d;}
    TextView text(String value,int size,int color){TextView t=new TextView(this);t.setText(value);t.setTextSize(size);t.setTextColor(color);t.setPadding(0,dp(5),0,dp(5));return t;}
    TextView heading(String value,int size){TextView t=text(value,size,INK);t.setTypeface(Typeface.DEFAULT,Typeface.BOLD);return t;}
    LinearLayout column(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);return l;}
    Button button(String value,Runnable action){Button b=new Button(this);b.setText(value);b.setAllCaps(false);b.setTextSize(14);b.setTextColor(BG);b.setBackground(shape(ACCENT,14));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(48));p.setMargins(0,dp(7),0,dp(7));b.setLayoutParams(p);b.setOnClickListener(v->action.run());return b;}
    void shell(String tab){screen=tab;generation++;main.removeCallbacks(refreshDownloads);root=column();root.setBackgroundColor(BG);root.setPadding(dp(20),dp(12),dp(20),dp(8));setContentView(root);
        root.setOnApplyWindowInsetsListener((v,insets)->{root.setPadding(dp(20),Math.max(dp(12),insets.getSystemWindowInsetTop()),dp(20),Math.max(dp(8),insets.getSystemWindowInsetBottom()));return insets.consumeSystemWindowInsets();});
        LinearLayout brand=new LinearLayout(this);brand.setGravity(Gravity.CENTER_VERTICAL);TextView logo=heading("▶  cubox chill",23);brand.addView(logo,new LinearLayout.LayoutParams(0,dp(52),1));TextView badge=text("BY SAYEM",10,ACCENT);badge.setLetterSpacing(.12f);brand.addView(badge);root.addView(brand);
        ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);body=column();body.setPadding(0,dp(12),0,dp(20));scroll.addView(body);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));
        nav=new LinearLayout(this);String[] labels={"Explore","Downloads","Updates","About"};String[] keys={"browse","downloads","updates","about"};for(int i=0;i<labels.length;i++){final int index=i;TextView n=text(labels[i],12,tab.equals(keys[i])?ACCENT:MUTED);n.setGravity(Gravity.CENTER);n.setPadding(0,dp(18),0,dp(14));n.setOnClickListener(v->{if(index==0)showBrowse();else if(index==1)showDownloads();else if(index==2)showUpdates();else showAbout();});nav.addView(n,new LinearLayout.LayoutParams(0,-2,1));}root.addView(nav);
    }
    LinearLayout card(){LinearLayout c=column();c.setPadding(dp(16),dp(12),dp(16),dp(12));c.setBackground(shape(CARD,18));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,dp(6),0,dp(8));c.setLayoutParams(p);return c;}
    interface Job{Object run()throws Exception;} interface Done{void accept(Object value)throws Exception;}
    void task(Job job,Done done){int token=generation;io.execute(()->{try{Object result=job.run();main.post(()->{if(isFinishing()||token!=generation)return;try{done.accept(result);}catch(Exception e){error(e.getMessage());}});}catch(Throwable e){main.post(()->{if(!isFinishing()&&token==generation)error(e.getMessage());});}});}
    void error(String message){if(progress!=null)progress.setVisibility(View.GONE);new AlertDialog.Builder(this).setTitle("Something interrupted that").setMessage(message==null?"Please try again.":message).setPositiveButton("OK",null).show();}
    void toast(String msg){Toast.makeText(this,msg,Toast.LENGTH_LONG).show();}
    void busy(String message){if(status!=null)status.setText(message);if(progress!=null)progress.setVisibility(View.VISIBLE);}
    void showBrowse(){shell("browse");body.addView(text("YOUR NEXT GOOD WATCH",11,ACCENT));body.addView(heading("Find it. Play it. Chill.",29));body.addView(text("Movies and series, across your favorite sources.",14,MUTED));
        Spinner sources=new Spinner(this);ArrayAdapter<String> adapter=new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,providerNames);sources.setAdapter(adapter);int selected=Arrays.asList(providerIds).indexOf(provider);sources.setSelection(Math.max(0,selected));body.addView(sources,new LinearLayout.LayoutParams(-1,dp(52)));
        sources.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(android.widget.AdapterView<?> p){}public void onItemSelected(android.widget.AdapterView<?> p,View v,int pos,long id){if(!provider.equals(providerIds[pos])){provider=providerIds[pos];catalog=new JSONArray();page=1;loadCatalog(false);}}});
        search=new EditText(this);search.setSingleLine();search.setTextColor(INK);search.setHintTextColor(MUTED);search.setHint("Search a movie or series");search.setText(query);search.setPadding(dp(16),dp(12),dp(16),dp(12));search.setBackground(shape(CARD,14));search.setImeOptions(android.view.inputmethod.EditorInfo.IME_ACTION_SEARCH);body.addView(search,new LinearLayout.LayoutParams(-1,dp(54)));
        Runnable runSearch=()->{query=search.getText().toString().trim();page=1;catalog=new JSONArray();((InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(search.getWindowToken(),0);loadCatalog(false);};search.setOnEditorActionListener((v,a,e)->{runSearch.run();return true;});body.addView(button("Search sources",runSearch));
        status=text("",13,MUTED);body.addView(status);progress=new ProgressBar(this);body.addView(progress,new LinearLayout.LayoutParams(dp(28),dp(28)));results=column();body.addView(results);
        if(catalog.length()>0){progress.setVisibility(View.GONE);renderCatalog();}else loadCatalog(false);
    }
    void loadCatalog(boolean append){generation++;String current=provider;String q=query;int requestedPage=page;
        if(q.isEmpty()&&!current.equals("moviebox")){progress.setVisibility(View.GONE);results.removeAllViews();status.setText(current.startsWith("bdix")?"Search this provider. BDIX access requires a supported ISP network.":"Enter a title to search this provider.");return;}
        busy("Searching "+providerNames[Arrays.asList(providerIds).indexOf(current)]+"…");
        task(()->Engine.request(this,Engine.json("op",q.isEmpty()?"home":"search","provider",current,"query",q,"page",requestedPage)),value->{JSONArray a=(JSONArray)value;if(!append)catalog=new JSONArray();for(int i=0;i<a.length();i++)catalog.put(a.get(i));progress.setVisibility(View.GONE);renderCatalog();});
    }
    void renderCatalog(){results.removeAllViews();status.setText(catalog.length()==0?"No titles returned. Try a different query or provider.":catalog.length()+" titles • tap to choose an episode or server");for(int i=0;i<catalog.length();i++){JSONObject item=catalog.optJSONObject(i);if(item==null)continue;LinearLayout row=card();row.addView(heading(item.optString("title"),18));row.addView(text(item.optString("media_type").toUpperCase(Locale.ROOT)+"  •  "+Engine.str(item,"year"),12,ACCENT));row.setOnClickListener(v->loadDetail(item));results.addView(row);}if(catalog.length()>0&&(provider.equals("moviebox")||provider.equals("dramachi")))results.addView(button("Load more",()->{page++;loadCatalog(true);}));}
    void loadDetail(JSONObject item){JSONObject id=item.optJSONObject("id");if(id==null)return;busy("Loading title…");task(()->Engine.request(this,Engine.json("op","details","provider",id.optString("provider"),"id",id.optString("value"))),v->{detail=(JSONObject)v;showDetail();});}
    void showDetail(){shell("detail");body.addView(text("‹  Back to explore",13,ACCENT));body.getChildAt(0).setOnClickListener(v->showBrowse());body.addView(heading(detail.optString("title"),28));body.addView(text(Engine.str(detail,"year")+"  •  "+Engine.str(detail,"duration")+"  •  "+detail.optString("media_type"),13,ACCENT));body.addView(text(Engine.str(detail,"description"),15,MUTED));
        JSONObject baseId=detail.optJSONObject("id");final String[] selectedId={baseId.optString("value")};
        JSONArray dubs=detail.optJSONArray("dubs");if(dubs!=null&&dubs.length()>1){body.addView(heading("Audio / edition",18));String[] labels=new String[dubs.length()];for(int i=0;i<labels.length;i++)labels[i]=dubs.optJSONObject(i).optString("label");Spinner spin=new Spinner(this);spin.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,labels));body.addView(spin);spin.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(android.widget.AdapterView<?> p){}public void onItemSelected(android.widget.AdapterView<?> p,View v,int pos,long id){selectedId[0]=dubs.optJSONObject(pos).optString("subject_id");}});}
        JSONArray seasons=detail.optJSONArray("seasons");if(seasons==null||seasons.length()==0){body.addView(button("Choose server & quality",()->loadReleases(baseId.optString("provider"),selectedId[0],0,0)));}
        else{body.addView(heading("Episodes",21));for(int i=0;i<seasons.length();i++){JSONObject season=seasons.optJSONObject(i);int number=season.optInt("number");body.addView(text("SEASON "+number,12,ACCENT));JSONArray episodes=season.optJSONArray("episodes");if(episodes!=null)for(int j=0;j<episodes.length();j++){JSONObject ep=episodes.optJSONObject(j);int en=ep.optInt("number");String name=Engine.str(ep,"title");Button b=button("Episode "+en+(name.isEmpty()?"":" · "+name),()->loadReleases(baseId.optString("provider"),selectedId[0],number,en));body.addView(b);}}}
        status=text("",13,MUTED);progress=new ProgressBar(this);progress.setVisibility(View.GONE);body.addView(status);body.addView(progress,new LinearLayout.LayoutParams(dp(28),dp(28)));
    }
    void loadReleases(String p,String id,int season,int episode){busy("Finding servers and available qualities…");task(()->Engine.request(this,Engine.json("op","releases","provider",p,"id",id,"season",season,"episode",episode)),value->{progress.setVisibility(View.GONE);JSONArray releases=(JSONArray)value;List<JSONObject> choices=new ArrayList<>();List<Integer> mirrors=new ArrayList<>();List<String> labels=new ArrayList<>();for(int i=0;i<releases.length();i++){JSONObject r=releases.getJSONObject(i);JSONArray ms=r.optJSONArray("mirrors");if(ms==null)continue;for(int j=0;j<ms.length();j++){choices.add(r);mirrors.add(j);long size=r.optLong("size_bytes",0);labels.add(Engine.str(r,"quality")+" · "+ms.getJSONObject(j).optString("label")+(size>0?" · "+String.format(Locale.ROOT,"%.1f GB",size/1073741824.0):"")+"\n"+r.optString("filename"));}}
        if(choices.isEmpty()){toast("No playable servers returned. Try another provider.");return;}new AlertDialog.Builder(this).setTitle("Choose a server / quality").setItems(labels.toArray(new String[0]),(dialog,index)->chooseAction(choices.get(index),mirrors.get(index),p,id,season,episode)).setNegativeButton("Cancel",null).show();});}
    void chooseAction(JSONObject release,int mirror,String p,String id,int season,int episode){new AlertDialog.Builder(this).setTitle("Ready when you are").setItems(new String[]{"▶  Play now","↓  Download for offline"},(d,which)->{busy(which==0?"Preparing playback…":"Preparing download…");task(()->Engine.request(this,Engine.json("op","resolve","provider",p,"release",release,"mirror",mirror,"download",which==1)),value->{JSONObject source=(JSONObject)value;String title=detail.optString("title")+(episode>0?" · S"+season+" E"+episode:"");String key=p+":"+id+":"+season+":"+episode;progress.setVisibility(View.GONE);if(which==0&&p.equals("moviebox")&&!Engine.str(release,"resource_id").isEmpty()){busy("Looking for subtitles…");task(()->{try{return Engine.request(this,Engine.json("op","captions","provider",p,"id",id,"season",season,"episode",episode,"resource_id",release.optString("resource_id")));}catch(Exception e){return new JSONArray();}},subs->{progress.setVisibility(View.GONE);chooseSubtitle(source,(JSONArray)subs,title,key,which==1);});}else launchOrDownload(source,title,key,which==1);});}).setNegativeButton("Cancel",null).show();}
    void chooseSubtitle(JSONObject source,JSONArray subs,String title,String key,boolean download){if(subs.length()==0){launchOrDownload(source,title,key,download);return;}String[] labels=new String[subs.length()+1];labels[0]="No external subtitle";for(int i=0;i<subs.length();i++)labels[i+1]=subs.optJSONObject(i).optString("name");new AlertDialog.Builder(this).setTitle("Subtitles").setItems(labels,(d,n)->{try{if(n>0)source.put("subtitle",subs.optJSONObject(n-1).optString("url"));}catch(JSONException ignored){}launchOrDownload(source,title,key,download);}).show();}
    void launchOrDownload(JSONObject source,String title,String key,boolean download){if(download){Offline.enqueue(this,source,title,key,error->{if(error!=null)error(error);else{toast("Added to your offline library");showDownloads();}});}else{startActivity(new Intent(this,PlayerActivity.class).putExtra("source",source.toString()).putExtra("title",title).putExtra("key",key));}}
    void showDownloads(){shell("downloads");renderDownloads();main.postDelayed(refreshDownloads,1500);}
    void renderDownloads(){body.removeAllViews();body.addView(text("TAKE THE GOOD STUFF WITH YOU",11,ACCENT));body.addView(heading("Your offline library",28));body.addView(text("Downloads stay in cubox chill. Keep the app installed to keep your library.",14,MUTED));
        List<Download> list=Offline.downloads();if(list.isEmpty()){LinearLayout empty=card();empty.addView(heading("A little quiet here",21));empty.addView(text("Find a movie or episode, pick a server, then choose Download for offline.",15,MUTED));body.addView(empty);return;}
        for(Download d:list){JSONObject meta=Offline.metadata(d);LinearLayout c=card();c.addView(heading(meta.optString("title"),18));String label=switch(d.state){case Download.STATE_COMPLETED->"Ready to watch offline";case Download.STATE_DOWNLOADING->"Downloading";case Download.STATE_STOPPED->"Paused";case Download.STATE_FAILED->"Failed · retry or resolve a fresh server link";case Download.STATE_REMOVING->"Removing";default->"Queued";};float percent=d.getPercentDownloaded();c.addView(text(label+(percent>=0?" · "+(int)percent+"%":"")+" · "+String.format(Locale.ROOT,"%.1f MB",d.getBytesDownloaded()/1048576.0),12,ACCENT));
            if(d.state==Download.STATE_COMPLETED)c.addView(button("Play offline",()->{JSONObject source=meta.optJSONObject("source");if(source!=null)startActivity(new Intent(this,PlayerActivity.class).putExtra("source",source.toString()).putExtra("title",meta.optString("title")).putExtra("key",d.request.id).putExtra("downloadId",d.request.id).putExtra("offline",true));}));
            else if(d.state!=Download.STATE_REMOVING)c.addView(button(d.state==Download.STATE_STOPPED||d.state==Download.STATE_FAILED?"Resume / retry":"Pause",()->{if(d.state==Download.STATE_FAILED)DownloadService.sendAddDownload(this,OfflineService.class,d.request,false);else DownloadService.sendSetStopReason(this,OfflineService.class,d.request.id,d.state==Download.STATE_STOPPED?0:1,false);renderDownloads();}));
            TextView remove=text("Remove download",13,MUTED);remove.setPadding(0,dp(12),0,dp(12));remove.setOnClickListener(v->new AlertDialog.Builder(this).setTitle("Remove this download?").setMessage(meta.optString("title")).setPositiveButton("Remove",(di,w)->DownloadService.sendRemoveDownload(this,OfflineService.class,d.request.id,false)).setNegativeButton("Keep",null).show());c.addView(remove);body.addView(c);
        }
    }
    String updateRepo(){return getSharedPreferences("settings",0).getString("repo",BuildConfig.UPDATE_REPOSITORY);}
    void showUpdates(){shell("updates");body.addView(text("KEEP THINGS RUNNING",11,ACCENT));body.addView(heading("Updates",30));LinearLayout c=card();c.addView(heading("cubox chill  "+BuildConfig.VERSION_NAME,20));c.addView(text("Developer: Sayem\nMovieBox engine: "+BuildConfig.ENGINE_VERSION+"\nBundled revision: "+BuildConfig.ENGINE_COMMIT.substring(0,8),14,MUTED));body.addView(c);
        body.addView(text("Engine changes are included in a new Android APK. A terminal release cannot be installed directly into this app.",14,MUTED));
        body.addView(button("Check MovieBox engine updates",()->task(()->Updates.latest("mesamirh/MovieBox-Tui"),r->showRelease((JSONObject)r,true))));
        body.addView(button("Check cubox chill updates",()->{String repo=updateRepo();if(repo.isEmpty()){toast("Set the cubox chill GitHub release repository below first.");return;}task(()->Updates.latest(repo),r->showRelease((JSONObject)r,false));}));
        body.addView(heading("App update source",19));body.addView(text("GitHub owner/repository for APK releases published by Sayem.",13,MUTED));EditText repo=new EditText(this);repo.setTextColor(INK);repo.setHintTextColor(MUTED);repo.setSingleLine();repo.setHint("owner/cubox-chill");repo.setText(updateRepo());body.addView(repo);body.addView(button("Save update source",()->{String value=repo.getText().toString().trim();if(!value.isEmpty()&&!Versions.validRepository(value)){error("Enter owner/repository, without a URL.");return;}getSharedPreferences("settings",0).edit().putString("repo",value).apply();toast("Update source saved");}));body.addView(text("Release checks run at most once per day when you open the app. Installation uses Android’s normal APK confirmation and requires the same signing key.",12,MUTED));
    }
    void showRelease(JSONObject r,boolean engine){String tag=r.optString("tag_name");boolean newer=Versions.newer(tag,engine?BuildConfig.ENGINE_VERSION:BuildConfig.VERSION_NAME);String message=newer?(engine?"A newer upstream engine is available. It must be integrated, tested, and shipped as a cubox chill APK.":"A newer cubox chill version is available."):"You are up to date with the latest published stable release.";String notes=Engine.str(r,"body");if(notes.length()>1800)notes=notes.substring(0,1800)+"…";AlertDialog.Builder dialog=new AlertDialog.Builder(this).setTitle((engine?"MovieBox-TUI ":"cubox chill ")+tag).setMessage(message+"\n\n"+notes).setNegativeButton("Close",null);String url=engine?r.optString("html_url"):Updates.apk(r);if(url.startsWith("https://github.com/"))dialog.setPositiveButton(engine?"Release notes":"Download APK",(d,w)->openUrl(url));dialog.show();}
    void checkInBackground(){long last=getSharedPreferences("settings",0).getLong("checked",0);if(System.currentTimeMillis()-last<86400000L)return;io.execute(()->{try{JSONObject engine=Updates.latest("mesamirh/MovieBox-Tui");boolean newer=Versions.newer(engine.optString("tag_name"),BuildConfig.ENGINE_VERSION);String repo=updateRepo();if(!repo.isEmpty()){JSONObject app=Updates.latest(repo);newer|=Versions.newer(app.optString("tag_name"),BuildConfig.VERSION_NAME);}getSharedPreferences("settings",0).edit().putLong("checked",System.currentTimeMillis()).apply();if(newer)main.post(()->{if(!isFinishing())toast("An update is available. Open the Updates tab.");});}catch(Exception ignored){}});}
    void showAbout(){shell("about");body.addView(text("MAKE ROOM FOR A GOOD STORY",11,ACCENT));body.addView(heading("cubox chill",34));body.addView(text("Developed by Sayem",19,ACCENT));body.addView(text("An independent Android client powered by the MovieBox-TUI provider engine and Android Media3.",16,MUTED));LinearLayout c=card();c.addView(heading("Five sources. One place.",20));c.addView(text("MovieBox · 4KHDHub · Dramachi\nCircleFTP (BDIX) · DhakaFlix (BDIX)\n\nBDIX sources require a compatible network. Source availability is controlled by the providers.",15,MUTED));body.addView(c);body.addView(button("MovieBox-TUI source & licenses",()->openUrl("https://github.com/mesamirh/MovieBox-Tui")));body.addView(button("Android Media3 source & license",()->openUrl("https://github.com/androidx/media")));body.addView(text("MovieBox-TUI: MIT / Apache-2.0\nMedia3: Apache-2.0\n\nUse content you are entitled to access. cubox chill does not host media and is not affiliated with the upstream developers.",13,MUTED));}
    void openUrl(String url){try{startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(url)));}catch(ActivityNotFoundException e){error("No browser is installed.");}}
}

